CREATE TRIGGER storage_items_insert AFTER INSERT ON items BEGIN SELECT CASE WHEN (NEW.image!='' AND NOT EXISTS(SELECT 1 FROM object_storage o WHERE o.user_id=NEW.user_id AND o.key=NEW.user_id||'/'||''||NEW.image AND o.state='ready')) OR (NEW.file_key!='' AND NOT EXISTS(SELECT 1 FROM object_storage o WHERE o.user_id=NEW.user_id AND o.key=NEW.user_id||'/'||'files/'||NEW.file_key AND o.state='ready')) OR EXISTS(WITH RECURSIVE refs(rest,id) AS (SELECT NEW.body,'' UNION ALL SELECT substr(rest,instr(rest,'/api/images/')+48),substr(rest,instr(rest,'/api/images/')+12,36) FROM refs WHERE instr(rest,'/api/images/')>0) SELECT 1 FROM refs WHERE length(id)=36 AND id NOT GLOB '*[^0-9a-f-]*' AND NOT EXISTS(SELECT 1 FROM object_storage o WHERE o.user_id=NEW.user_id AND o.key=NEW.user_id||'/'||refs.id AND o.state='ready')) OR EXISTS(WITH RECURSIVE refs(rest,id) AS (SELECT NEW.body,'' UNION ALL SELECT substr(rest,instr(rest,'/api/files/')+47),substr(rest,instr(rest,'/api/files/')+11,36) FROM refs WHERE instr(rest,'/api/files/')>0) SELECT 1 FROM refs WHERE length(id)=36 AND id NOT GLOB '*[^0-9a-f-]*' AND NOT EXISTS(SELECT 1 FROM object_storage o WHERE o.user_id=NEW.user_id AND o.key=NEW.user_id||'/files/'||refs.id AND o.state='ready')) OR EXISTS(SELECT 1 FROM object_storage o WHERE o.user_id=NEW.user_id AND o.state='purging' AND (NEW.file_key=substr(o.key,-36) OR NEW.image=substr(o.key,-36) OR (instr(NEW.body,'/api/images/'||substr(o.key,-36))>0 OR instr(NEW.body,'/api/files/'||substr(o.key,-36))>0))) THEN RAISE(ABORT,'Upload was canceled during cleanup') END; INSERT OR IGNORE INTO storage_usage(user_id,metadata_bytes,object_bytes) SELECT NEW.user_id,(SELECT COALESCE(SUM(2048+length(CAST(json_quote(q.id) AS BLOB))+length(CAST(json_quote(q.user_id) AS BLOB))+length(CAST(json_quote(q.url) AS BLOB))+length(CAST(json_quote(q.title) AS BLOB))+length(CAST(json_quote(q.note) AS BLOB))+length(CAST(json_quote(q.tags) AS BLOB))+length(CAST(json_quote(q.collection) AS BLOB))+length(CAST(json_quote(q.status) AS BLOB))+length(CAST(json_quote(q.kind) AS BLOB))+length(CAST(json_quote(q.file_key) AS BLOB))+length(CAST(json_quote(q.file_name) AS BLOB))+length(CAST(json_quote(q.file_type) AS BLOB))+length(CAST(json_quote(q.image) AS BLOB))+length(CAST(json_quote(q.body) AS BLOB))+length(CAST(json_quote(q.language) AS BLOB))),0) FROM items q WHERE q.user_id=NEW.user_id)+(SELECT COALESCE(SUM(2048+length(CAST(json_quote(q.id) AS BLOB))+length(CAST(json_quote(q.user_id) AS BLOB))+length(CAST(json_quote(q.name) AS BLOB))+length(CAST(json_quote(q.parent_id) AS BLOB))+length(CAST(json_quote(q.icon) AS BLOB))+length(CAST(json_quote(q.color) AS BLOB))+length(CAST(json_quote(q.image) AS BLOB))),0) FROM collections q WHERE q.user_id=NEW.user_id)+(SELECT COALESCE(SUM(2048+length(CAST(json_quote(q.item_id) AS BLOB))+length(CAST(json_quote(q.user_id) AS BLOB))+length(CAST(json_quote(q.snapshot) AS BLOB))),0) FROM item_revisions q WHERE q.user_id=NEW.user_id)+(SELECT COALESCE(SUM(2048+length(CAST(json_quote(q.id) AS BLOB))+length(CAST(json_quote(q.user_id) AS BLOB))+length(CAST(json_quote(q.item_id) AS BLOB))+length(CAST(json_quote(q.mime) AS BLOB))),0) FROM attachments q WHERE q.user_id=NEW.user_id)+(SELECT COALESCE(SUM(2048+length(CAST(json_quote(q.user_id) AS BLOB))+length(CAST(json_quote(q.data) AS BLOB))),0) FROM preferences q WHERE q.user_id=NEW.user_id)+(SELECT COALESCE(SUM(2048+length(CAST(json_quote(q.item_id) AS BLOB))+length(CAST(json_quote(q.user_id) AS BLOB))+length(CAST(json_quote(q.state) AS BLOB))),0) FROM item_health q WHERE q.user_id=NEW.user_id)+(SELECT COUNT(*)*2048 FROM object_storage WHERE user_id=NEW.user_id),(SELECT COALESCE(SUM(bytes),0) FROM object_storage WHERE user_id=NEW.user_id) WHERE NOT EXISTS(SELECT 1 FROM storage_usage WHERE user_id=NEW.user_id); UPDATE storage_usage SET metadata_bytes=metadata_bytes+(2048+length(CAST(json_quote(NEW.id) AS BLOB))+length(CAST(json_quote(NEW.user_id) AS BLOB))+length(CAST(json_quote(NEW.url) AS BLOB))+length(CAST(json_quote(NEW.title) AS BLOB))+length(CAST(json_quote(NEW.note) AS BLOB))+length(CAST(json_quote(NEW.tags) AS BLOB))+length(CAST(json_quote(NEW.collection) AS BLOB))+length(CAST(json_quote(NEW.status) AS BLOB))+length(CAST(json_quote(NEW.kind) AS BLOB))+length(CAST(json_quote(NEW.file_key) AS BLOB))+length(CAST(json_quote(NEW.file_name) AS BLOB))+length(CAST(json_quote(NEW.file_type) AS BLOB))+length(CAST(json_quote(NEW.image) AS BLOB))+length(CAST(json_quote(NEW.body) AS BLOB))+length(CAST(json_quote(NEW.language) AS BLOB))) WHERE user_id=NEW.user_id AND changes()=0; SELECT CASE WHEN metadata_bytes>33554432 THEN RAISE(ABORT,'Account content storage limit reached') END FROM storage_usage WHERE user_id=NEW.user_id; END;
